
local jelqk=[==[]==]
local tgoby=
(function(...)
local cqu={193,213,147,143,178,115,14,219,94,208,218,107,198,230,141,178,143,176,195,94,68,22,92,66}
local xkmw=bit32 or bit
local exphq=xkmw.bxor
for vmx=1,#cqu do cqu[vmx]=exphq(cqu[vmx],(119*vmx+207)%256) end
local xib="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local cz={}
for gyqf=1,#xib do cz[xib:byte(gyqf)]=gyqf-1 end
local function sf(str)
  local R={} local acc,nb=0,0
  for fjuo=1,#str do
    local v=cz[str:byte(fjuo)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function ragl(key,data)
  local S={} for qivwl=0,255 do S[qivwl]=qivwl end
  local j=0
  for ywjqz=0,255 do
    j=(j+S[ywjqz]+key[(ywjqz%#key)+1])%256
    S[ywjqz],S[j]=S[j],S[ywjqz]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(exphq(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=ragl(cqu,sf(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local qgvo=nf()
return function(big) return qgvo(big) end
end)(...)

return tgoby(jelqk)
